-group"><label>ISBN</label><input name="ISBN" required></div><div class="form-group"><label>Book Name</label><input name="bookName" required></div><div class="form-group"><label>Author Name</label><input name="authorName" required></div><div class="form-group"><label>Price</label><input type="number" name="price" min="0" required></div><div class="form-group"><label>Quantity</label><input type="number" name="quantity" min="0" required></div></div><button class="primary-action">Add Book</button></form></section><section class="dashboard-card section-panel" id="add-student-section" hidden><div class="section-heading"><span class="section-icon">03</span><div><h2>Add Student</h2><p>Create a student account.</p></div></div><form method="post" action="../addStudent.php" class="dashboard-form"><div class="form-grid"><div class="form-group"><label>Name</label><input name="studentName" required></div><div class="form-group"><label>Student ID</label><input name="studentID" required></div><div class="form-group"><label>Email</label><input type="email" name="studentEmail" required></div><div class="form-group"><label>Password</label><input type="password" name="studentPassword" required></div><div class="form-group"><label>Degree</label><select name="degree" required><option value="">Select Degree</option><option value="bscs">BSCS</option><option value="bsai">BSAI</option><option value="bsit">BSIT</option><option value="bscys">BSCYS</option><option value="bsse">BSSE</option></select></div></div><button class="primary-action">Add Student</button></form></section></main><script src="../assets/js/script.js"></script></body></html>